let currentFramework = 'rtf';
        function setFramework(fw) {
            currentFramework = fw;
            // Toggle Visual States of Buttons (Active State Update)
            document.querySelectorAll('.fw-btn').forEach(btn => {
                btn.classList.remove('fw-btn-active', 'bg-blue-50', 'text-blue-700', 'border-blue-600');
                btn.classList.add('bg-white', 'text-slate-600', 'border-transparent');
            });
            // Set Active
            const activeBtn = document.getElementById(`btn-${fw}`);
            activeBtn.classList.add('fw-btn-active', 'bg-blue-50', 'text-blue-700', 'border-blue-600');
            activeBtn.classList.remove('bg-white', 'text-slate-600', 'border-transparent');
            // Handle UI changes for specific frameworks
            const shotFields = document.getElementById('shot-fields');
            if (fw === 'shot') {
                shotFields.classList.remove('hidden');
            } else {
                shotFields.classList.add('hidden');
            }
            buildPrompt();
        }
        // Expanded V2 Logic from New File
        function buildPrompt() {
            const role = document.getElementById('role').value.trim() || "[ACTOR PERSONA]";
            const goal = document.getElementById('goal').value.trim() || "[CORE MISSION]";
            const format = document.getElementById('format').value.trim() || "[DEFAULT FORMAT]";
            const context = document.getElementById('context').value.trim();
            const constraints = document.getElementById('constraints').value.trim();
            const examples = document.getElementById('examples').value.trim();
            let finalPrompt = "";
            switch (currentFramework) {
                case 'rtf':
                    finalPrompt = `[ROLE]\nAct as a ${role}.\n\n[TASK]\n${goal}\n\n`;
                    if (context) finalPrompt += `[CONTEXT]\n${context}\n\n`;
                    if (constraints) finalPrompt += `[LIMITS]\n${constraints}\n\n`;
                    finalPrompt += `[FORMAT]\nDeliver in: ${format}`;
                    break;
                case 'cot':
                    finalPrompt = `You are a ${role}.\n\nBACKGROUND: ${context || 'N/A'}\n\nOBJECTIVE: ${goal}\n\n`;
                    finalPrompt += `REASONING PROTOCOL:\n1. Deconstruct the request into components.\n2. Think step-by-step through the logic.\n3. Verify your findings.\n4. Provide the final result in ${format} format.`;
                    if (constraints) finalPrompt += `\n\nCONSTRAINTS: ${constraints}`;
                    break;
                case 'xml':
                    finalPrompt = `Persona: ${role}\n\n<task>\n${goal}\n</task>\n\n`;
                    if (context) finalPrompt += `<context>\n${context}\n</context>\n\n`;
                    if (constraints) finalPrompt += `<rules>\n${constraints}\n</rules>\n\n`;
                    finalPrompt += `Output: <${format.toLowerCase().replace(/\s/g, '_')}>`;
                    break;
                case 'shot':
                    finalPrompt = `Act as ${role}. I will show you a pattern. Mirror it exactly for the final input.\n\n`;
                    if (examples) finalPrompt += `EXAMPLES:\n${examples}\n\n`;
                    if (context) finalPrompt += `DATA:\n${context}\n\n`;
                    finalPrompt += `TASK:\n${goal}\n\nFORMAT: ${format}`;
                    break;
                case 'cod':
                    finalPrompt = `As a ${role}, your goal is to generate an increasingly dense summary of the context below.\n\n`;
                    finalPrompt += `CONTEXT:\n${context || '[SOURCE]'}\n\n`;
                    finalPrompt += `PROTOCOL (Chain of Density):\n1. Generate an initial summary of 50 words.\n2. Identify 5 missing critical entities.\n3. Rewrite the summary incorporating those entities without increasing length.\n4. Repeat step 3 three times.\n\nFINAL FORMAT: ${format}`;
                    break;
            }
            document.getElementById('output').textContent = finalPrompt;
            updateStats(finalPrompt);
            updateHealth();
        }
        // New Feature: Stats
        function updateStats(text) {
            const words = text.split(/\s+/).filter(w => w.length > 0).length;
            const tokens = Math.ceil(text.length / 4); // Heuristic
            document.getElementById('stats').textContent = `Words: ${words} | Approx Tokens: ${tokens}`;
        }
        // New Feature: Health Bar
        function updateHealth() {
            let score = 0;
            const fields = ['role', 'goal', 'format', 'context'];
            fields.forEach(f => {
                if (document.getElementById(f).value.trim().length > 3) score += 25;
            });
            const bar = document.getElementById('score-bar');
            const val = document.getElementById('score-val');
            const tip = document.getElementById('score-tip');
            bar.style.width = `${score}%`;
            val.textContent = `${score}%`;
            if (score < 50) tip.textContent = "Weak signal. Add more context or persona details.";
            else if (score < 100) tip.textContent = "Strong signal. Almost ready for execution.";
            else tip.textContent = "Professional Grade. High specificity achieved.";
        }
        function copyToClipboard() {
            const text = document.getElementById('output').textContent;
            // Clipboard fallback for iframe/restricted environments
            const textArea = document.createElement("textarea");
            textArea.value = text;
            document.body.appendChild(textArea);
            textArea.select();
            document.execCommand('copy');
            document.body.removeChild(textArea);
            // Visual feedback
            const btn = document.getElementById('copy-btn');
            const original = btn.innerHTML;
            btn.innerHTML = `<svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2.5" d="M5 13l4 4L19 7"></path></svg> Copied!`;
            btn.classList.replace('bg-blue-600', 'bg-emerald-600');
            setTimeout(() => {
                btn.innerHTML = original;
                btn.classList.replace('bg-emerald-600', 'bg-blue-600');
            }, 2000);
        }
        // New Feature: Download
        function downloadPrompt() {
            const text = document.getElementById('output').textContent;
            const blob = new Blob([text], { type: 'text/plain' });
            const url = window.URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `architected-prompt-${new Date().getTime()}.txt`;
            a.click();
        }
        // New Feature: Reset Modal
        function showResetModal() {
            document.getElementById('reset-modal').classList.replace('hidden', 'flex');
        }
        function closeResetModal() {
            document.getElementById('reset-modal').classList.replace('flex', 'hidden');
        }
        function performReset() {
            ['role', 'goal', 'format', 'context', 'constraints', 'examples'].forEach(id => {
                const el = document.getElementById(id);
                if (el) el.value = '';
            });
            buildPrompt();
            closeResetModal();
        }
        // --- SCROLL LOGIC ---
        // Initialize Calculation on Load
        document.addEventListener('DOMContentLoaded', () => {
            // Set initial button states manually to match HTML default
            setFramework('rtf');
            // Listen to all inputs for live updates
            ['role', 'goal', 'format', 'context', 'constraints', 'examples'].forEach(id => {
                document.getElementById(id).addEventListener('input', buildPrompt);
            });
        });
